 "overview": "<svg class=\"chart\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 720 230\" role=\"img\" aria-label=\"特征与目标分离：井底循环温度预测\"><title>特征与目标分离：井底循环温度预测</title><g fill=\"var(--ink)\" font-family=\"system-ui,Microsoft YaHei,sans-serif\"><text x=\"24\" y=\"30\" font-size=\"18\" font-weight=\"600\">特征与目标分离：井底循环温度预测</text><rect x=\"25\" y=\"85\" width=\"210\" height=\"110\" rx=\"8\" fill=\"var(--paper-2,#eef3f8)\"/><text x=\"130\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">01</text><text x=\"130\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">可用输入</text><text x=\"130\" y=\"174\" font-size=\"12\" text-anchor=\"middle\">井深 · 循环排量</text><path d=\"M237 140h15l-5-5m5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#168273)\" stroke-width=\"2\"/><rect x=\"255\" y=\"85\" width=\"210\" height=\"110\" rx=\"8\" fill=\"var(--paper-2,#eef3f8)\"/><text x=\"360\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">02</text><text x=\"360\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">建模或搜索</text><text x=\"360\" y=\"174\" font-size=\"12\" text-anchor=\"middle\">多变量回归</text><path d=\"M467 140h15l-5-5m5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#168273)\" stroke-width=\"2\"/><rect x=\"485\" y=\"85\" width=\"210\" height=\"110\" rx=\"8\" fill=\"var(--paper-2,#eef3f8)\"/><text x=\"590\" y=\"112\" font-size=\"13\" text-anchor=\"middle\">03</text><text x=\"590\" y=\"146\" font-size=\"16\" text-anchor=\"middle\">验证与复核</text><text x=\"590\" y=\"174\" font-size=\"12\" text-anchor=\"middle\">比较60条测试记录的MAE</text></g></svg>",
